import type { PageProps } from '@rshono/core';
import summary from '../../content/benchmarks-summary.json';
import { Layout } from './layout';

/**
 * `/benchmarks` — five numbers, and a link to the rest.
 *
 * The page deliberately does *not* render `content/benchmarks.md`. That file is generated by
 * `pnpm --filter @rshono/benchmarks site:publish` and is the complete result set — every metric, all
 * three columns, whichever way the row went — and it is still served verbatim at
 * [`/benchmarks.md`](../routes/benchmark-markdown.ts). Putting all 190 lines of it on a web page made
 * the page a data dump rather than an answer, so what is here is the handful of metrics worth deciding
 * on and a link to the whole thing.
 *
 * {@link KEY_METRICS} names them by id from `benchmarks-summary.json`, so the values, the winners and
 * the gaps are the generated ones — nothing on this page is a hand-typed number that could drift from
 * the run it came from.
 */
export default function Benchmarks({ url }: PageProps<'/benchmarks'>) {
  return (
    <Layout
      title="Benchmarks"
      description="One app built three ways — rshono, Next.js and TanStack Start — measured on payload, build, startup and throughput."
      canonical={url.href}
    >
      <h1 className="text-3xl font-semibold tracking-tight text-zinc-900 dark:text-white">Benchmarks</h1>
      <p className="mt-3 mb-10 text-lg text-pretty text-zinc-600 dark:text-zinc-400">
        One app, built three ways to the same spec. Measured on {summary.machine}, {summary.measuredOn}.
      </p>

      <Metrics />
      <Caveats />
      <Reproduce />
    </Layout>
  );
}

const BENCH_URL = 'https://github.com/rshono/rshono/tree/main/packages/benchmarks';

/**
 * The metrics the page shows, by id, in three tables.
 *
 * `label` is an optional override, and only ever for repetition: under a *Throughput* heading four
 * rows each ending in the word "throughput" reads worse than four route paths. The numbers, the
 * winners and the hints are the generated ones either way — nothing here restates a measurement.
 *
 * The rest of the result set is one link away, which is what keeps this list to what someone is
 * actually choosing between.
 */
const GROUPS: Array<{ title: string; rows: Array<{ id: string; label?: string }> }> = [
  {
    title: 'Load & build',
    rows: [{ id: 'payload-home' }, { id: 'build-cold' }, { id: 'devstart-cold' }, { id: 'coldstart' }],
  },
  {
    title: 'Throughput',
    rows: [
      { id: 'home-rps', label: '/ — prerendered' },
      { id: 'ssr-rps', label: '/ssr — 100 rows' },
      { id: 'interactive-rps', label: '/interactive' },
      { id: 'api-rps', label: '/api/health' },
    ],
  },
  {
    title: 'Memory',
    rows: [
      { id: 'rss-idle', label: 'Idle' },
      { id: 'rss-loaded', label: 'After load' },
      { id: 'churn', label: 'Churn per 1k requests' },
    ],
  },
];

function Metrics() {
  return (
    <>
      {GROUPS.map((group) => (
        <MetricTable key={group.title} title={group.title} rows={group.rows} />
      ))}
    </>
  );
}

function MetricTable({ title, rows }: { title: string; rows: Array<{ id: string; label?: string }> }) {
  const metrics = rows
    .map((row) => {
      const metric = summary.metrics.find((candidate) => candidate.id === row.id);
      return metric ? { ...metric, label: row.label ?? metric.label } : undefined;
    })
    .filter((metric) => metric !== undefined);

  if (metrics.length === 0) return null;

  return (
    <table className="mb-8 w-full border-collapse text-sm">
      <caption className="mb-2 text-left font-medium text-zinc-900 dark:text-white">{title}</caption>
      <thead>
        <tr className="border-b border-zinc-300 dark:border-zinc-700">
          <th className="w-2/5 py-2 pr-4 text-left font-normal text-zinc-500 dark:text-zinc-400">
            <span className="sr-only">Metric</span>
          </th>
          {summary.targets.map((target) => (
            <th
              key={target.id}
              className={`py-2 pl-4 text-right font-medium ${
                target.id === 'rshono' ? 'text-zinc-900 dark:text-white' : 'text-zinc-500 dark:text-zinc-400'
              }`}
            >
              {target.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {metrics.map((metric) => (
          <tr key={metric.id} className="border-b border-zinc-200 dark:border-zinc-800">
            <th scope="row" className="py-3 pr-4 text-left font-normal">
              <span className="block text-zinc-900 dark:text-white">{metric.label}</span>
              <span className="block text-xs text-zinc-500 dark:text-zinc-400">{metric.hint}</span>
            </th>
            {summary.targets.map((target) => {
              const value = metric.values.find((candidate) => candidate.target === target.id);
              const best = metric.winner === target.id;
              return (
                <td
                  key={target.id}
                  className={`py-3 pl-4 text-right tabular-nums ${
                    best ? 'font-medium text-zinc-900 dark:text-white' : 'text-zinc-500 dark:text-zinc-400'
                  }`}
                >
                  {value?.display ?? '—'}
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function Caveats() {
  return (
    <ul className="mt-2 space-y-2 text-sm text-zinc-500 dark:text-zinc-400">
      <li>Payload and size figures are exact. Timings are laptop numbers — treat spreads under ~10% as a tie.</li>
      <li>
        Throughput is a floor check. All three render through the same React, so <code>/ssr</code> and <code>/interactive</code> largely compare React
        with itself; <code>/api/health</code> has no React on the path and is where the frameworks themselves are visible.
      </li>
      <li>
        Memory is a high-water mark, not retention — RSS includes garbage V8 has not collected, and each route is driven for a fixed eight seconds, so
        the server answering the most requests allocates the most. All three are given the same 256 MB old-space budget, and churn per 1k requests is
        the row that removes the bias.
      </li>
      <li>
        rshono loses on production install size: {installSizes()}. Every metric is in the{' '}
        <a href="/benchmarks.md" data-native>
          full report
        </a>
        .
      </li>
    </ul>
  );
}

/** The one row rshono loses, quoted from the same generated data as the table. */
function installSizes(): string {
  const install = summary.metrics.find((metric) => metric.id === 'install');
  if (!install) return 'see the full report';
  return install.values.map((value) => `${value.label} ${value.display}`).join(', ');
}

function Reproduce() {
  return (
    <section className="mt-10 border-t border-zinc-200 pt-6 dark:border-zinc-800">
      <p className="mb-3 text-sm text-zinc-600 dark:text-zinc-400">
        One spec file says what each app must do, and the payload runner asserts it — a route that stopped rendering the same thing fails the check
        rather than quietly reporting a smaller number.
      </p>
      <pre className="mb-3 overflow-x-auto rounded-lg border border-zinc-200 bg-zinc-50 p-3 text-sm dark:border-zinc-800 dark:bg-zinc-900">
        <code>{'pnpm --filter @rshono/benchmarks setup:apps\npnpm --filter @rshono/benchmarks bench'}</code>
      </pre>
      <p className="text-sm text-zinc-600 dark:text-zinc-400">
        <a href={BENCH_URL} data-native>
          packages/benchmarks
        </a>{' '}
        has the method and what it deliberately does not measure.
      </p>
    </section>
  );
}
